import logging

log = logging.getLogger("exceptions")


class LogException(Exception):
    def __init__(self, msg):
        self.msg = msg
        log.debug("Exception: '{}'. Msg: '{}'".format(self.__class__.__name__, msg))

    def __str__(self):
        return self.msg


class WrongByteLength(LogException):
    def __init__(self, msg_name, expected_len, actual_len):
        self.msg_name = msg_name
        self.expected_len = expected_len
        self.actual_len = actual_len
        super(WrongByteLength, self).__init__(msg=str(self))

    def __str__(self):
        err_str = (
            "message_name: {msg_name}, "
            "expected_len: {expected_len}, "
            "actual_len: {actual_len}".format(
                msg_name=self.msg_name,
                expected_len=self.expected_len,
                actual_len=self.actual_len,
            )
        )
        return err_str


class RootHasNoChildren(LogException):
    def __init__(self, root):
        self.root = root
        super(RootHasNoChildren, self).__init__(msg=str(self))

    def __str__(self):
        err_str = repr(self.root)
        return err_str


